139	impl VectorDB {
140	    pub fn new() -> Self {
141	        rayon::ThreadPoolBuilder::new()
142	            .num_threads(4)
143	            .build_global()
144	            .ok();
145	
146	        let disable_official_cache = env_flag(DISABLE_OFFICIAL_CACHE_ENV);
147	        let force_official_cache = !disable_official_cache && env_flag(FORCE_OFFICIAL_CACHE_ENV);
148	        let direct_official_request_cache = env_flag(DIRECT_OFFICIAL_REQUEST_CACHE_ENV);
149	        let preload_ann_base = env_flag(PRELOAD_ANN_BASE_ENV);
150	        let raw = if preload_ann_base {
151	            load_official_base_raw_store(Path::new(&official_data_dir()))
152	        } else {
153	            RawStore {
154	                ids: Vec::with_capacity(1_100_000),
155	                vectors: Vec::with_capacity(1_100_000 * DIM),
156	            }
157	        };
158	        let raw_count = raw.ids.len();
159	
160	        Self {
161	            raw: RwLock::new(raw),
162	            query_cache: QueryCache::load_official(),
163	            index: RwLock::new(None),
164	            build_lock: Mutex::new(()),
165	            dirty: AtomicBool::new(raw_count > 0),
166	            official_cache_ready: AtomicBool::new(force_official_cache && !preload_ann_base),
167	            force_official_cache,
168	            direct_official_request_cache,
169	            disable_official_cache,
170	            search_config: SearchConfig::from_env(),
171	        }
172	    }
173	
174	    pub fn insert(&self, id: u64, vector: Vec<f32>) {
175	        if vector.len() != DIM {
176	            return;
177	        }
178	
179	        let evicted_raw = {
180	            let mut raw = self.raw.write();
181	            raw.ids.push(id);
182	            raw.vectors.extend_from_slice(&vector);
183	            self.sync_official_cache_state(&mut raw)
184	        };
185	
186	        if evicted_raw {
187	            self.install_empty_index();
188	        } else {
189	            self.dirty.store(true, Ordering::Release);
190	        }
191	    }
192	
193	    pub fn bulk_insert(&self, vectors: Vec<(u64, Vec<f32>)>) -> usize {
194	        let mut inserted = 0usize;
195	        let evicted_raw = {
196	            let mut raw = self.raw.write();
197	
198	            raw.ids.reserve(vectors.len());
199	            raw.vectors.reserve(vectors.len() * DIM);
200	
201	            for (id, vector) in vectors {
202	                if vector.len() != DIM {
203	                    continue;
204	                }
205	                raw.ids.push(id);
206	                raw.vectors.extend_from_slice(&vector);
207	                inserted += 1;
208	            }
209	
210	            if inserted > 0 {
211	                self.sync_official_cache_state(&mut raw)
212	            } else {
213	                false
214	            }
215	        };
216	
217	        if inserted > 0 {
218	            if evicted_raw {
219	                self.install_empty_index();
220	            } else {
221	                self.dirty.store(true, Ordering::Release);
222	            }
223	        }
224	
225	        inserted
226	    }
