228	    pub fn search(&self, vector: &[f32], top_k: u32) -> Vec<SearchResult> {
229	        if vector.len() != DIM || top_k == 0 {
230	            return Vec::new();
231	        }
232	
233	        let top_k = usize::min(top_k as usize, MAX_RESULTS);
234	        if let Some(results) = self.cached_search(vector, top_k) {
235	            return results;
236	        }
237	
238	        let index = self.ensure_index();
239	        if index.cluster_ids.is_empty() {
240	            return Vec::new();
241	        }
242	
243	        let config = self.search_config;
244	
245	        let mut primary_distances = [0.0f32; PRIMARY_CLUSTERS];
246	        distance::l2_distance_batch(
247	            vector,
248	            &index.primary_centroids,
249	            PRIMARY_CLUSTERS,
250	            &mut primary_distances,
251	        );
252	
253	        let mut best_primary_ids = Vec::with_capacity(config.primary_probe);
254	        let mut best_primary_distances = Vec::with_capacity(config.primary_probe);
255	        for (cluster_id, &dist) in primary_distances.iter().enumerate() {
256	            push_smallest(
257	                &mut best_primary_ids,
258	                &mut best_primary_distances,
259	                config.primary_probe,
260	                cluster_id,

261	                dist,
262	            );
263	        }
264	        sort_pairs(&mut best_primary_ids, &mut best_primary_distances);
265	
266	        let mut best_cluster_ids = Vec::with_capacity(config.cluster_probe);
267	        let mut best_cluster_distances = Vec::with_capacity(config.cluster_probe);
268	        let mut secondary_distances = [0.0f32; SECONDARY_CLUSTERS];
269	        let secondary_span = SECONDARY_CLUSTERS * DIM;
270	
271	        for &primary_id in best_primary_ids.iter() {
272	            let start = primary_id * secondary_span;
273	            let end = start + secondary_span;
274	            distance::l2_distance_batch(
275	                vector,
276	                &index.secondary_centroids[start..end],
277	                SECONDARY_CLUSTERS,
278	                &mut secondary_distances,
279	            );
280	
281	            for (secondary_id, &dist) in secondary_distances.iter().enumerate() {
282	                let cluster_id = primary_id * SECONDARY_CLUSTERS + secondary_id;
283	                push_smallest(
284	                    &mut best_cluster_ids,
285	                    &mut best_cluster_distances,
286	                    config.cluster_probe,
287	                    cluster_id,
288	                    dist,
289	                );
290	            }
291	        }
292	        sort_pairs(&mut best_cluster_ids, &mut best_cluster_distances);
293	
294	        let quantized_query = QuantizedQuery::new(vector, index.quant_min, index.quant_scale);
295	        let mut prescored = CandidateHeap::new(usize::max(config.prescore_candidates, top_k));
296	
297	        if config.cluster_prune {
298	            let mut selected_clusters = Vec::with_capacity(best_cluster_ids.len());
299	            for &cluster_id in best_cluster_ids.iter() {
300	                let start = cluster_id * DIM;
301	                let centroid_distance = distance::l2_squared_u8(
302	                    &quantized_query.values,
303	                    &index.secondary_centroids_u8[start..start + DIM],
304	                );
305	                selected_clusters.push((centroid_distance, cluster_id));
306	            }
307	            selected_clusters.sort_unstable_by_key(|&(distance, _)| distance);
308	
309	            for (centroid_distance, cluster_id) in selected_clusters.into_iter() {
310	                if prescored.is_full()
311	                    && cluster_lower_bound(
312	                        centroid_distance,
313	                        index.cluster_quantized_radii[cluster_id],
314	                    ) >= prescored.worst_distance()
315	                {
316	                    continue;
317	                }
318	
319	                let start = index.cluster_offsets[cluster_id];
320	                let end = index.cluster_offsets[cluster_id + 1];
321	                if start == end {
322	                    continue;
323	                }
324	
325	                scan_cluster_quantized(
326	                    &quantized_query,
327	                    &index.cluster_vectors_u8[start * DIM..end * DIM],
328	                    start,
329	                    &mut prescored,
330	                );
331	            }
332	        } else {
333	            for &cluster_id in best_cluster_ids.iter() {
334	                let start = index.cluster_offsets[cluster_id];
335	                let end = index.cluster_offsets[cluster_id + 1];
336	                if start == end {
337	                    continue;
338	                }
339	
340	                scan_cluster_quantized(
341	                    &quantized_query,
342	                    &index.cluster_vectors_u8[start * DIM..end * DIM],
343	                    start,
344	                    &mut prescored,
345	                );
346	            }
347	        }
348	
349	        let mut topk = TopK::new(top_k);
350	        rerank_prescored_candidates(vector, &index, &prescored, &mut topk);
351	        topk.into_results()
352	    }
