380	    fn ensure_index(&self) -> Arc<HierarchicalIndex> {
381	        if !self.dirty.load(Ordering::Acquire) {
382	            if let Some(index) = self.index.read().as_ref().cloned() {
383	                return index;
384	            }
385	        }
386	
387	        let _guard = self.build_lock.lock();
388	        if !self.dirty.load(Ordering::Acquire) {
389	            if let Some(index) = self.index.read().as_ref().cloned() {
390	                return index;
391	            }
392	        }
393	
394	        let raw = self.raw.read();
395	        let count = raw.ids.len();
396	
397	        if count == 0 {
398	            let empty = Arc::new(empty_hierarchical_index());
399	            *self.index.write() = Some(empty.clone());
400	            self.dirty.store(false, Ordering::Release);
401	            return empty;
402	        }
403	
404	        let training = collect_training_sample(&raw.vectors, count);
405	        let primary_centroids = run_kmeans(
406	            &training,
407	            training.len() / DIM,
408	            PRIMARY_CLUSTERS,
409	            PRIMARY_KMEANS_ITERS,
410	        );
411	
412	        let sample_primary_assignments: Vec<usize> = training
413	            .par_chunks_exact(DIM)
414	            .map(|sample| nearest_centroid(sample, &primary_centroids, PRIMARY_CLUSTERS))
415	            .collect();
416	
417	        let mut primary_buckets: Vec<Vec<f32>> =
418	            (0..PRIMARY_CLUSTERS).map(|_| Vec::new()).collect();
419	        for (sample_idx, &primary_id) in sample_primary_assignments.iter().enumerate() {
420	            let start = sample_idx * DIM;
421	            primary_buckets[primary_id].extend_from_slice(&training[start..start + DIM]);
422	        }
423	
424	        let secondary_chunks: Vec<Vec<f32>> = primary_buckets
425	            .into_par_iter()
426	            .enumerate()
427	            .map(|(primary_id, bucket)| {
428	                if bucket.is_empty() {
429	                    return duplicate_centroid(
430	                        &primary_centroids[primary_id * DIM..(primary_id + 1) * DIM],
431	                        SECONDARY_CLUSTERS,
432	                    );
433	                }
434	
435	                if bucket.len() / DIM <= SECONDARY_CLUSTERS {
436	                    return expand_bucket_centroids(
437	                        &bucket,
438	                        &primary_centroids[primary_id * DIM..(primary_id + 1) * DIM],
439	                    );
440	                }
441	
442	                run_kmeans(
443	                    &bucket,
444	                    bucket.len() / DIM,
445	                    SECONDARY_CLUSTERS,
446	                    SECONDARY_KMEANS_ITERS,
447	                )
448	            })
449	            .collect();
450	
451	        let mut secondary_centroids =
452	            Vec::with_capacity(PRIMARY_CLUSTERS * SECONDARY_CLUSTERS * DIM);
453	        for chunk in secondary_chunks {
454	            secondary_centroids.extend_from_slice(&chunk);
455	        }
456	
457	        let assignments: Vec<usize> = (0..count)
458	            .into_par_iter()
459	            .map(|idx| {
460	                let start = idx * DIM;
461	                let vector = &raw.vectors[start..start + DIM];
462	                let primary_id = nearest_centroid(vector, &primary_centroids, PRIMARY_CLUSTERS);
463	                let secondary_start = primary_id * SECONDARY_CLUSTERS * DIM;
464	                let secondary_id = nearest_centroid(
465	                    vector,
466	                    &secondary_centroids
467	                        [secondary_start..secondary_start + SECONDARY_CLUSTERS * DIM],
468	                    SECONDARY_CLUSTERS,
469	                );
470	                primary_id * SECONDARY_CLUSTERS + secondary_id
471	            })
472	            .collect();
473	
474	        let total_clusters = PRIMARY_CLUSTERS * SECONDARY_CLUSTERS;
475	        let mut cluster_sizes = vec![0usize; total_clusters];
476	        for &cluster_id in assignments.iter() {
477	            cluster_sizes[cluster_id] += 1;
478	        }
479	
480	        let mut cluster_offsets = vec![0usize; total_clusters + 1];
481	        for idx in 0..total_clusters {
482	            cluster_offsets[idx + 1] = cluster_offsets[idx] + cluster_sizes[idx];
483	        }
484	
485	        let (quant_min, quant_scale) = compute_quantization_params(&raw.vectors);
486	        let mut secondary_centroids_u8 = vec![0u8; secondary_centroids.len()];
487	        for (idx, centroid) in secondary_centroids.iter().enumerate() {
488	            secondary_centroids_u8[idx] = quantize_value(*centroid, quant_min, quant_scale);
489	        }
490	        let mut cluster_ids = vec![0u64; count];
491	        let mut cluster_vectors_f16 = vec![f16::from_f32(0.0); count * DIM];
492	        let mut cluster_vectors_u8 = vec![0u8; count * DIM];
493	        let mut cluster_quantized_radii_sq = vec![0u32; total_clusters];
494	        let mut write_positions = cluster_offsets[..total_clusters].to_vec();
495	
496	        for (vector_idx, &cluster_id) in assignments.iter().enumerate() {
497	            let position = write_positions[cluster_id];
498	            write_positions[cluster_id] += 1;
499	            cluster_ids[position] = raw.ids[vector_idx];
500	
501	            let src = vector_idx * DIM;
502	            let dst = position * DIM;
503	            let centroid_start = cluster_id * DIM;
504	            let mut radius_sq = 0u32;
505	            for dim in 0..DIM {
506	                let value = raw.vectors[src + dim];
507	                cluster_vectors_f16[dst + dim] = f16::from_f32(value);
508	                let quantized = quantize_value(value, quant_min, quant_scale);
509	                cluster_vectors_u8[dst + dim] = quantized;
510	                let delta = quantized as i32 - secondary_centroids_u8[centroid_start + dim] as i32;
511	                radius_sq += (delta * delta) as u32;
512	            }
513	            cluster_quantized_radii_sq[cluster_id] =
514	                cluster_quantized_radii_sq[cluster_id].max(radius_sq);
515	        }
516	        let cluster_quantized_radii = cluster_quantized_radii_sq
517	            .into_iter()
518	            .map(|radius_sq| (radius_sq as f64).sqrt().ceil() as u16)
519	            .collect();
