 28	#[inline(always)]
 29	pub fn nearest_centroid(query: &[f32], centroids_flat: &[f32], count: usize) -> usize {
 30	    debug_assert_eq!(query.len(), DIM);
 31	    debug_assert!(centroids_flat.len() >= count * DIM);
 32	
 33	    let mut best_idx = 0usize;
 34	    let mut best_dist = f32::MAX;
 35	
 36	    for idx in 0..count {
 37	        let start = idx * DIM;
 38	        let dist = l2_squared(query, &centroids_flat[start..start + DIM]);
 39	        if dist < best_dist {
 40	            best_dist = dist;
 41	            best_idx = idx;
 42	        }
 43	    }
 44	
 45	    best_idx
 46	}
