 78	pub fn l2_squared_f16(query: &[f32], vector: &[f16]) -> f32 {
 79	    debug_assert_eq!(query.len(), DIM);
 80	    debug_assert_eq!(vector.len(), DIM);
 81	
 82	    #[cfg(target_arch = "x86_64")]
 83	    {
 84	        if is_x86_feature_detected!("avx") && is_x86_feature_detected!("f16c") {
 85	            return unsafe { l2_squared_f16_f16c(query, vector) };
