151	#[target_feature(enable = "avx512f")]
152	unsafe fn l2_squared_avx512(a: &[f32], b: &[f32]) -> f32 {
153	    use std::arch::x86_64::*;
154	
155	    let a_ptr = a.as_ptr();
156	    let b_ptr = b.as_ptr();
157	
158	    let d0 = _mm512_sub_ps(_mm512_loadu_ps(a_ptr), _mm512_loadu_ps(b_ptr));
159	    let mut sum = _mm512_mul_ps(d0, d0);
160	
161	    let d1 = _mm512_sub_ps(
162	        _mm512_loadu_ps(a_ptr.add(16)),
163	        _mm512_loadu_ps(b_ptr.add(16)),
164	    );
165	    sum = _mm512_fmadd_ps(d1, d1, sum);
166	
167	    let d2 = _mm512_sub_ps(
168	        _mm512_loadu_ps(a_ptr.add(32)),
169	        _mm512_loadu_ps(b_ptr.add(32)),
170	    );
171	    sum = _mm512_fmadd_ps(d2, d2, sum);
172	
173	    let d3 = _mm512_sub_ps(
174	        _mm512_loadu_ps(a_ptr.add(48)),
175	        _mm512_loadu_ps(b_ptr.add(48)),
176	    );
177	    sum = _mm512_fmadd_ps(d3, d3, sum);
178	
179	    let d4 = _mm512_sub_ps(
180	        _mm512_loadu_ps(a_ptr.add(64)),
181	        _mm512_loadu_ps(b_ptr.add(64)),
182	    );
183	    sum = _mm512_fmadd_ps(d4, d4, sum);
184	
185	    let d5 = _mm512_sub_ps(
186	        _mm512_loadu_ps(a_ptr.add(80)),
187	        _mm512_loadu_ps(b_ptr.add(80)),
188	    );
189	    sum = _mm512_fmadd_ps(d5, d5, sum);
190	
191	    let d6 = _mm512_sub_ps(
192	        _mm512_loadu_ps(a_ptr.add(96)),
193	        _mm512_loadu_ps(b_ptr.add(96)),
194	    );
195	    sum = _mm512_fmadd_ps(d6, d6, sum);
196	
197	    let d7 = _mm512_sub_ps(
198	        _mm512_loadu_ps(a_ptr.add(112)),
199	        _mm512_loadu_ps(b_ptr.add(112)),
200	    );
201	    sum = _mm512_fmadd_ps(d7, d7, sum);
202	
203	    _mm512_reduce_add_ps(sum)
204	}
