206	#[cfg(target_arch = "x86_64")]
207	#[target_feature(enable = "avx512f")]
208	unsafe fn l2_distance_batch_avx512(
209	    query: &[f32],
210	    vectors_flat: &[f32],
211	    n_vectors: usize,
212	    distances: &mut [f32],
213	) {
214	    use std::arch::x86_64::*;
215	
216	    let q_ptr = query.as_ptr();
217	    let q0 = _mm512_loadu_ps(q_ptr);
218	    let q1 = _mm512_loadu_ps(q_ptr.add(16));
219	    let q2 = _mm512_loadu_ps(q_ptr.add(32));
220	    let q3 = _mm512_loadu_ps(q_ptr.add(48));
221	    let q4 = _mm512_loadu_ps(q_ptr.add(64));
222	    let q5 = _mm512_loadu_ps(q_ptr.add(80));
223	    let q6 = _mm512_loadu_ps(q_ptr.add(96));
224	    let q7 = _mm512_loadu_ps(q_ptr.add(112));
225	
226	    let v_ptr = vectors_flat.as_ptr();
227	
228	    for idx in 0..n_vectors {
229	        let base = v_ptr.add(idx * DIM);
230	
231	        let d0 = _mm512_sub_ps(q0, _mm512_loadu_ps(base));
232	        let mut sum = _mm512_mul_ps(d0, d0);
233	
234	        let d1 = _mm512_sub_ps(q1, _mm512_loadu_ps(base.add(16)));
235	        sum = _mm512_fmadd_ps(d1, d1, sum);
236	
237	        let d2 = _mm512_sub_ps(q2, _mm512_loadu_ps(base.add(32)));
238	        sum = _mm512_fmadd_ps(d2, d2, sum);
239	
240	        let d3 = _mm512_sub_ps(q3, _mm512_loadu_ps(base.add(48)));
241	        sum = _mm512_fmadd_ps(d3, d3, sum);
242	
243	        let d4 = _mm512_sub_ps(q4, _mm512_loadu_ps(base.add(64)));
244	        sum = _mm512_fmadd_ps(d4, d4, sum);
245	
246	        let d5 = _mm512_sub_ps(q5, _mm512_loadu_ps(base.add(80)));
247	        sum = _mm512_fmadd_ps(d5, d5, sum);
248	
249	        let d6 = _mm512_sub_ps(q6, _mm512_loadu_ps(base.add(96)));
250	        sum = _mm512_fmadd_ps(d6, d6, sum);
251	
252	        let d7 = _mm512_sub_ps(q7, _mm512_loadu_ps(base.add(112)));
253	        sum = _mm512_fmadd_ps(d7, d7, sum);
254	
255	        distances[idx] = _mm512_reduce_add_ps(sum);
256	    }
257	}
