259	#[cfg(target_arch = "x86_64")]
260	#[target_feature(enable = "avx2")]
261	unsafe fn l2_squared_avx2(a: &[f32], b: &[f32]) -> f32 {
262	    use std::arch::x86_64::*;
263	
264	    let a_ptr = a.as_ptr();
265	    let b_ptr = b.as_ptr();
266	
267	    let mut sum0 = _mm256_setzero_ps();
268	    let mut sum1 = _mm256_setzero_ps();
269	    let mut sum2 = _mm256_setzero_ps();
270	    let mut sum3 = _mm256_setzero_ps();
271	
272	    for offset in (0..DIM).step_by(32) {
273	        let d0 = _mm256_sub_ps(
274	            _mm256_loadu_ps(a_ptr.add(offset)),
275	            _mm256_loadu_ps(b_ptr.add(offset)),
276	        );
277	        let d1 = _mm256_sub_ps(
278	            _mm256_loadu_ps(a_ptr.add(offset + 8)),
279	            _mm256_loadu_ps(b_ptr.add(offset + 8)),
280	        );
281	        let d2 = _mm256_sub_ps(
