604	    #[inline(always)]
605	    fn push(&mut self, id: u64, distance: f32) {
606	        if self.limit == 0 {
607	            return;
608	        }
609	
610	        if self.len < self.limit {
611	            self.ids[self.len] = id;
612	            self.distances[self.len] = distance;
613	            self.len += 1;
614	            self.sift_up(self.len - 1);
615	            return;
616	        }
617	
618	        if distance >= self.distances[0] {
619	            return;
620	        }
