627	    fn into_results(self) -> Vec<SearchResult> {
628	        let mut pairs: Vec<(f32, u64)> = (0..self.len)
629	            .map(|idx| (self.distances[idx], self.ids[idx]))
630	            .collect();
631	        pairs.sort_unstable_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
632	        pairs
633	            .drain(..)
634	            .map(|(distance, id)| SearchResult {
635	                id,
636	                distance: distance as f64,
637	            })
638	            .collect()
639	    }
