641	    fn sift_up(&mut self, mut idx: usize) {
642	        while idx > 0 {
643	            let parent = (idx - 1) / 2;
644	            if self.distances[idx] <= self.distances[parent] {
645	                break;
646	            }
647	            self.distances.swap(idx, parent);
648	            self.ids.swap(idx, parent);
649	            idx = parent;
650	        }
651	    }
