653	    fn sift_down(&mut self, mut idx: usize) {
654	        loop {
655	            let left = idx * 2 + 1;
656	            let right = left + 1;
657	            let mut largest = idx;
658	
659	            if left < self.len && self.distances[left] > self.distances[largest] {
660	                largest = left;
661	            }
662	            if right < self.len && self.distances[right] > self.distances[largest] {
663	                largest = right;
664	            }
665	            if largest == idx {
666	                break;
667	            }
668	
669	            self.distances.swap(idx, largest);
670	            self.ids.swap(idx, largest);
671	            idx = largest;
672	        }
673	    }
