189	fn handle_connection(
190	    mut stream: TcpStream,
191	    db: Arc<VectorDB>,
192	    stats: Option<Arc<RequestStats>>,
193	    split_cached_search_response: bool,
194	    post_write_spin: u64,
195	    close_after_cached_search: bool,
196	    early_cached_search_headers: bool,
197	    early_cached_search_partial_read_bytes: usize,
198	) -> io::Result<()> {
199	    stream.set_nodelay(true)?;
200	
201	    let mut buffer = Vec::with_capacity(64 * 1024);
202	    let mut search_header_template = None;
203	    loop {
204	        let read_start = stats.as_ref().map(|_| Instant::now());
205	        let request = match if early_cached_search_headers {
206	            read_request_with_early_cached_search(
207	                &mut stream,
208	                &mut buffer,
209	                db.as_ref(),
210	                close_after_cached_search,
211	                &mut search_header_template,
212	                early_cached_search_partial_read_bytes,
213	            )
214	        } else {
215	            read_request_standard(&mut stream, &mut buffer)
216	                .map(|request| request.map(ReadOutcome::Parsed))
217	        } {
218	            Ok(Some(request)) => request,
219	            Ok(None) => {
220	                if let Some(stats) = stats.as_ref() {
221	                    stats.flush_snapshot();
222	                }
223	                return Ok(());
224	            }
225	            Err(err) if err.kind() == io::ErrorKind::InvalidData => {
226	                let write_start = stats.as_ref().map(|_| Instant::now());
227	                stream.write_all(BAD_REQUEST_RESPONSE)?;
228	                if let Some(stats) = stats.as_ref() {
229	                    let read_ns = elapsed_ns(read_start);
230	                    let write_ns = elapsed_ns(write_start);
231	                    stats.record_request(
232	                        RequestKind::BadRequest,
233	                        0,
234	                        BAD_REQUEST_RESPONSE.len() as u64,
235	                        read_ns,
236	                        0,
237	                        write_ns,
238	                    );
239	                    stats.flush_snapshot();
240	                }
241	                return Ok(());
242	            }
243	            Err(err) if err.kind() == io::ErrorKind::UnexpectedEof => {
244	                if let Some(stats) = stats.as_ref() {
245	                    stats.flush_snapshot();
246	                }
247	                return Ok(());
248	            }
249	            Err(err) => return Err(err),
250	        };
251	        match request {
252	            ReadOutcome::Parsed(request) => {
253	                let read_ns = elapsed_ns(read_start);
254	
255	                let process_start = stats.as_ref().map(|_| Instant::now());
256	                let outcome = process_request(
257	                    &db,
258	                    &buffer[request.body_start..request.body_end],
259	                    request.route,
260	                    split_cached_search_response,
261	                    close_after_cached_search,
262	                );
263	                let process_ns = elapsed_ns(process_start);
264	
265	                let write_start = stats.as_ref().map(|_| Instant::now());
266	                write_response(&mut stream, &outcome.response, outcome.split_response)?;
267	                let write_ns = elapsed_ns(write_start);
268	
269	                if let Some(stats) = stats.as_ref() {
270	                    stats.record_request(
271	                        outcome.kind,
272	                        request.consumed as u64,
273	                        outcome.response.len() as u64,
274	                        read_ns,
275	                        process_ns,
276	                        write_ns,
277	                    );
278	                }
279	                consume_buffer(&mut buffer, request.consumed);
280	
281	                if !outcome.keep_open {
282	                    if let Some(stats) = stats.as_ref() {
283	                        stats.flush_snapshot();
284	                    }
285	                    return Ok(());
286	                }
287	
288	                if post_write_spin > 0 && outcome.kind.is_request_cache_hit() {
289	                    prefetch_after_write(&stream, &mut buffer, post_write_spin)?;
290	                }
291	            }
292	            ReadOutcome::CachedSearch(request) => {
293	                let read_ns = elapsed_ns(read_start);
294	                let write_start = stats.as_ref().map(|_| Instant::now());
295	                write_response(&mut stream, &request.response, false)?;
296	                let write_ns = elapsed_ns(write_start);
297	
298	                if let Some(stats) = stats.as_ref() {
299	                    stats.record_request(
300	                        RequestKind::SearchRequestCacheFastHit,
301	                        request.consumed as u64,
302	                        request.response.len() as u64,
303	                        read_ns,
304	                        0,
305	                        write_ns,
306	                    );
307	                }
308	                consume_buffer(&mut buffer, request.consumed);
309	
310	                if !request.keep_open {
311	                    if let Some(stats) = stats.as_ref() {
312	                        stats.flush_snapshot();
313	                    }
314	                    return Ok(());
315	                }
316	
317	                if post_write_spin > 0 {
318	                    prefetch_after_write(&stream, &mut buffer, post_write_spin)?;
319	                }
320	            }
321	            ReadOutcome::EarlyCachedSearch(request) => {
322	                let write_start = stats.as_ref().map(|_| Instant::now());
323	                stream.write_all(request.response_header.as_ref())?;
324	                finish_request_body(&mut stream, &mut buffer, request.body_end)?;
325	                stream.write_all(request.response_body.as_ref())?;
326	                let write_ns = elapsed_ns(write_start);
327	                let read_ns = elapsed_ns(read_start);
328	
329	                if let Some(stats) = stats.as_ref() {
330	                    stats.record_request(
331	                        RequestKind::SearchRequestCacheEarlyHit,
332	                        request.consumed as u64,
333	                        (request.response_header.len() + request.response_body.len()) as u64,
334	                        read_ns,
335	                        0,
336	                        write_ns,
337	                    );
338	                }
339	                consume_buffer(&mut buffer, request.consumed);
340	            }
341	        }
342	    }
343	}
