1225	fn compute_quantization_params(vectors: &[f32]) -> (f32, f32) {
1226	    let mut min_value = f32::INFINITY;
1227	    let mut max_value = f32::NEG_INFINITY;
1228	
1229	    for &value in vectors.iter() {
1230	        min_value = min_value.min(value);
1231	        max_value = max_value.max(value);
1232	    }
1233	
1234	    if !min_value.is_finite() || !max_value.is_finite() || max_value <= min_value {
1235	        return (0.0, 0.0);
1236	    }
1237	
1238	    (min_value, 255.0 / (max_value - min_value))
1239	}
