1242	fn quantize_value(value: f32, quant_min: f32, quant_scale: f32) -> u8 {
1243	    if quant_scale <= 0.0 {
1244	        return 0;
1245	    }
1246	
1247	    ((value - quant_min) * quant_scale)
1248	        .round()
1249	        .clamp(0.0, 255.0) as u8
1250	}
