402	    }
403	
404	    let lo = _mm256_castps256_ps128(sum);
405	    let hi = _mm256_extractf128_ps(sum, 1);
406	    let sum = _mm_add_ps(lo, hi);
407	    let sum = _mm_hadd_ps(sum, sum);
